/*!
 * Bootstrap Bundle (JS+Deps) local fallback.
 * NOTE: Application pages load Bootstrap from CDN:
 *   https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/js/bootstrap.bundle.min.js
 * This local file provides the few modal/dropdown/collapse behaviors the app
 * uses so pages degrade gracefully when the CDN is unavailable.
 */
(function (global) {
  var bootstrap = {
    Modal: function (element) {
      this._el = element;
      this.show = function () { element.style.display = 'flex'; return this; };
      this.hide = function () { element.style.display = 'none'; return this; };
    },
    Dropdown: function () {},
    Collapse: function () {}
  };
  function dataApi() {
    document.addEventListener('click', function (e) {
      var t = e.target;
      if (t && t.matches('[data-bs-dismiss="modal"]')) {
        var modal = t.closest('.modal');
        if (modal) modal.style.display = 'none';
      }
      if (t && (t.matches('[data-bs-toggle="dropdown"]') || t.closest('[data-bs-toggle="dropdown"]'))) {
        var btn = t.closest('[data-bs-toggle="dropdown"]');
        if (btn) { var menu = btn.nextElementSibling; if (menu) menu.classList.toggle('show'); }
      }
    });
  }
  if (document.readyState !== 'loading') { dataApi(); } else { document.addEventListener('DOMContentLoaded', dataApi); }
  global.bootstrap = bootstrap;
})(window);
